MODULE_SOURCE='\nfrom __future__ import annotations\n\nimport re\nimport unicodedata\nfrom dataclasses import dataclass\nfrom types import MappingProxyType\nfrom typing import Any, Mapping, Tuple\n\nfrom .universal_market_discovery_foundation import (\n    UMD_SUBSYSTEM_ID,\n    ImmutableLineage,\n    deterministic_sha256,\n)\n\nUMD_094_BUILD_ID = "UMD-094"\nUMD_094_BUILD_NAME = "Market Normalization Foundation"\nUMD_094_REVISION = "UMD_094_MARKET_NORMALIZATION_FOUNDATION_V1"\nUMD_094_SCHEMA_VERSION = "1.0.0"\n\nPROHIBITED_CAPABILITIES = (\n    "network_invocation", "persistence", "mutation", "publication", "execution",\n)\n\n_WS = re.compile(r"\\\\s+")\n_PUNCT = re.compile(r"[^a-z0-9]+")\n\n\ndef _text(value: str, field_name: str, *, allow_empty: bool = False) -> str:\n    if not isinstance(value, str):\n        raise TypeError(f"{field_name} must be a string")\n    value = unicodedata.normalize("NFKC", value)\n    value = _WS.sub(" ", value.strip())\n    if not value and not allow_empty:\n        raise ValueError(f"{field_name} must not be empty")\n    return value\n\n\ndef _key(value: str, field_name: str) -> str:\n    value = _text(value, field_name).casefold()\n    value = _PUNCT.sub("-", value).strip("-")\n    if not value:\n        raise ValueError(f"{field_name} must contain letters or digits")\n    return value\n\n\ndef _freeze(value: Mapping[str, Any] | None) -> Mapping[str, Any]:\n    if value is None:\n        value = {}\n    if not isinstance(value, Mapping):\n        raise TypeError("metadata must be a mapping")\n    return MappingProxyType(dict(sorted((str(k), v) for k, v in value.items())))\n\n\ndef _tuple_text(values, field_name: str) -> Tuple[str, ...]:\n    if isinstance(values, str):\n        raise TypeError(f"{field_name} must be an iterable of strings")\n    result = tuple(_text(v, field_name) for v in values)\n    if len(set(x.casefold() for x in result)) != len(result):\n        raise ValueError(f"{field_name} must not contain duplicates")\n    return result\n\n\n@dataclass(frozen=True, slots=True)\nclass MarketObservation:\n    venue: str\n    venue_market_id: str\n    title: str\n    description: str = ""\n    category: str = "uncategorized"\n    status: str = "unknown"\n    close_time: str = ""\n    settlement_time: str = ""\n    outcomes: Tuple[str, ...] = ()\n    rules: str = ""\n    source_ref: str = ""\n    metadata: Mapping[str, Any] | None = None\n\n    def __post_init__(self) -> None:\n        object.__setattr__(self, "venue", _text(self.venue, "venue"))\n        object.__setattr__(self, "venue_market_id", _text(self.venue_market_id, "venue_market_id"))\n        object.__setattr__(self, "title", _text(self.title, "title"))\n        object.__setattr__(self, "description", _text(self.description, "description", allow_empty=True))\n        object.__setattr__(self, "category", _text(self.category, "category"))\n        object.__setattr__(self, "status", _text(self.status, "status"))\n        object.__setattr__(self, "close_time", _text(self.close_time, "close_time", allow_empty=True))\n        object.__setattr__(self, "settlement_time", _text(self.settlement_time, "settlement_time", allow_empty=True))\n        object.__setattr__(self, "outcomes", _tuple_text(self.outcomes, "outcome"))\n        object.__setattr__(self, "rules", _text(self.rules, "rules", allow_empty=True))\n        object.__setattr__(self, "source_ref", _text(self.source_ref, "source_ref", allow_empty=True))\n        object.__setattr__(self, "metadata", _freeze(self.metadata))\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "venue": self.venue, "venue_market_id": self.venue_market_id,\n            "title": self.title, "description": self.description,\n            "category": self.category, "status": self.status,\n            "close_time": self.close_time, "settlement_time": self.settlement_time,\n            "outcomes": self.outcomes, "rules": self.rules,\n            "source_ref": self.source_ref, "metadata": self.metadata,\n        }\n\n    @property\n    def observation_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\n@dataclass(frozen=True, slots=True)\nclass NormalizedMarket:\n    venue: str\n    venue_key: str\n    venue_market_id: str\n    title: str\n    title_key: str\n    description: str\n    category: str\n    category_key: str\n    status: str\n    status_key: str\n    close_time: str\n    settlement_time: str\n    outcomes: Tuple[str, ...]\n    outcome_keys: Tuple[str, ...]\n    rules: str\n    source_ref: str\n    source_observation_hash: str\n    metadata: Mapping[str, Any]\n    lineage: ImmutableLineage\n\n    def __post_init__(self) -> None:\n        for name in ("venue", "venue_key", "venue_market_id", "title", "title_key", "category", "category_key", "status", "status_key", "source_observation_hash"):\n            if not isinstance(getattr(self, name), str) or not getattr(self, name):\n                raise ValueError(f"{name} must be non-empty")\n        object.__setattr__(self, "metadata", _freeze(self.metadata))\n        if self.lineage.subsystem_id != UMD_SUBSYSTEM_ID:\n            raise ValueError("lineage must belong to UMD")\n        if self.lineage.build_id != UMD_094_BUILD_ID:\n            raise ValueError("lineage build_id must be UMD-094")\n        if self.source_observation_hash not in self.lineage.parent_hashes:\n            raise ValueError("lineage must include source observation hash")\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "venue": self.venue, "venue_key": self.venue_key,\n            "venue_market_id": self.venue_market_id, "title": self.title,\n            "title_key": self.title_key, "description": self.description,\n            "category": self.category, "category_key": self.category_key,\n            "status": self.status, "status_key": self.status_key,\n            "close_time": self.close_time, "settlement_time": self.settlement_time,\n            "outcomes": self.outcomes, "outcome_keys": self.outcome_keys,\n            "rules": self.rules, "source_ref": self.source_ref,\n            "source_observation_hash": self.source_observation_hash,\n            "metadata": self.metadata, "lineage": self.lineage,\n        }\n\n    @property\n    def normalized_market_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\nclass MarketNormalizer:\n    __slots__ = ()\n\n    def normalize(self, observation: MarketObservation, *, lineage: ImmutableLineage) -> NormalizedMarket:\n        if not isinstance(observation, MarketObservation):\n            raise TypeError("observation must be MarketObservation")\n        return NormalizedMarket(\n            venue=observation.venue,\n            venue_key=_key(observation.venue, "venue"),\n            venue_market_id=observation.venue_market_id,\n            title=observation.title,\n            title_key=_key(observation.title, "title"),\n            description=observation.description,\n            category=observation.category,\n            category_key=_key(observation.category, "category"),\n            status=observation.status,\n            status_key=_key(observation.status, "status"),\n            close_time=observation.close_time,\n            settlement_time=observation.settlement_time,\n            outcomes=observation.outcomes,\n            outcome_keys=tuple(_key(v, "outcome") for v in observation.outcomes),\n            rules=observation.rules,\n            source_ref=observation.source_ref,\n            source_observation_hash=observation.observation_hash,\n            metadata=observation.metadata,\n            lineage=lineage,\n        )\n\n\ndef build_umd_094_certification_manifest() -> Mapping[str, Any]:\n    data = {\n        "subsystem_id": "UMD", "build_id": UMD_094_BUILD_ID,\n        "revision": UMD_094_REVISION, "schema_version": UMD_094_SCHEMA_VERSION,\n        "upstream_build": "UMD-093", "mode": "deterministic_read_only_normalization",\n        "prohibited_capabilities": PROHIBITED_CAPABILITIES,\n        "network_enabled": False, "persistence_enabled": False,\n        "mutation_enabled": False, "publication_enabled": False, "execution_enabled": False,\n    }\n    return MappingProxyType({**data, "manifest_hash": deterministic_sha256(data)})\n\n\ndef verify_umd_094_market_normalization_foundation() -> bool:\n    manifest = build_umd_094_certification_manifest()\n    return all((manifest["build_id"] == "UMD-094", manifest["upstream_build"] == "UMD-093", not manifest["network_enabled"], not manifest["persistence_enabled"], not manifest["mutation_enabled"], not manifest["publication_enabled"], not manifest["execution_enabled"]))\n'
TEST_SOURCE='\nfrom __future__ import annotations\nimport unittest\nfrom dataclasses import FrozenInstanceError\nfrom datetime import datetime, timezone\nfrom qseries_v2.universal_market_discovery.universal_market_discovery_foundation import ImmutableLineage\nfrom qseries_v2.universal_market_discovery.umd_094_market_normalization import (\n    UMD_094_REVISION, MarketObservation, MarketNormalizer,\n    build_umd_094_certification_manifest, verify_umd_094_market_normalization_foundation,\n)\n\nFIXED = datetime(2026, 8, 8, 12, 0, tzinfo=timezone.utc)\n\ndef lineage(parent):\n    return ImmutableLineage(subsystem_id="UMD", build_id="UMD-094", revision=UMD_094_REVISION, schema_version="1.0.0", parent_hashes=(parent,), source_refs=("fixture://umd-094",), created_at=FIXED)\n\nclass TestUMD094(unittest.TestCase):\n    def observation(self):\n        return MarketObservation(venue=" Kalshi ", venue_market_id="KX-BTC-001", title="  Will BTC exceed $100K?  ", category=" Crypto ", status=" Open ", outcomes=(" Yes ", "No"), source_ref="fixture://market/1", metadata={"read_only": True})\n    def test_foundation(self): self.assertTrue(verify_umd_094_market_normalization_foundation())\n    def test_normalization(self):\n        o=self.observation(); m=MarketNormalizer().normalize(o, lineage=lineage(o.observation_hash))\n        self.assertEqual(m.venue_key,"kalshi"); self.assertEqual(m.title_key,"will-btc-exceed-100k"); self.assertEqual(m.outcome_keys,("yes","no"))\n    def test_deterministic(self):\n        o=self.observation(); l=lineage(o.observation_hash); n=MarketNormalizer(); self.assertEqual(n.normalize(o,lineage=l).normalized_market_hash,n.normalize(o,lineage=l).normalized_market_hash)\n    def test_lineage_bound(self):\n        o=self.observation(); bad=ImmutableLineage(subsystem_id="UMD",build_id="UMD-094",revision=UMD_094_REVISION,schema_version="1.0.0",parent_hashes=("0"*64,),source_refs=("fixture://bad",),created_at=FIXED)\n        with self.assertRaises(ValueError): MarketNormalizer().normalize(o,lineage=bad)\n    def test_immutable(self):\n        o=self.observation(); m=MarketNormalizer().normalize(o,lineage=lineage(o.observation_hash))\n        with self.assertRaises((FrozenInstanceError,AttributeError)): m.title="x"\n        with self.assertRaises(TypeError): m.metadata["x"]=1\n    def test_side_effects(self):\n        m=build_umd_094_certification_manifest(); self.assertFalse(any(m[k] for k in ("network_enabled","persistence_enabled","mutation_enabled","publication_enabled","execution_enabled")))\n\nif __name__ == "__main__":\n    print("="*72); print(" UMD-094 CERTIFICATION TEST"); print(" MARKET NORMALIZATION FOUNDATION"); print("="*72)\n    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(TestUMD094))\n    if not result.wasSuccessful(): raise SystemExit(1)\n    m=build_umd_094_certification_manifest(); print(); print(f"[PASS] Build: {m[\'build_id\']}"); print(f"[PASS] Revision: {m[\'revision\']}"); print(f"[PASS] Manifest hash: {m[\'manifest_hash\']}"); print("[PASS] Certified UMD-093 baseline consumed read-only"); print("[PASS] Deterministic immutable normalization certified"); print("[PASS] Network, persistence, publication, and execution disabled"); print("[DONE] UMD-094 CERTIFIED")\n'
UPSTREAM_MODULE='umd_093_read_model'
UPSTREAM_VERIFIER='verify_umd_093_raw_venue_market_observation_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model'
EXPORTED_NAMES=('UMD_094_REVISION', 'MarketObservation', 'NormalizedMarket', 'MarketNormalizer', 'build_umd_094_certification_manifest', 'verify_umd_094_market_normalization_foundation')

def verify_upstream():
    sys.path.insert(0,str(ROOT))
    try:
        mod=importlib.import_module("qseries_v2.universal_market_discovery."+UPSTREAM_MODULE)
        verifier=getattr(mod,UPSTREAM_VERIFIER,None)
        if verifier is None: raise RuntimeError(f"Certified upstream verifier missing: {UPSTREAM_MODULE}.{UPSTREAM_VERIFIER}")
        if verifier() is not True: raise RuntimeError(f"Certified upstream verification failed: {UPSTREAM_MODULE}")
    finally:
        if str(ROOT) in sys.path: sys.path.remove(str(ROOT))

def write_exact(path,source):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(source.lstrip("\n"),encoding="utf-8",newline="\n")
    os.replace(tmp,path)

def update_init():
    current=INIT.read_text(encoding="utf-8") if INIT.exists() else ""
    marker=f"# UMD-094 exports"
    block=marker+"\nfrom ."+MODULE.stem+" import (\n"+"".join(f"    {name},\n" for name in EXPORTED_NAMES)+")\n"
    if marker not in current: write_exact(INIT,current.rstrip()+"\n\n"+block)

def verify_current():
    sys.path.insert(0,str(ROOT))
    try:
        name="qseries_v2.universal_market_discovery."+MODULE.stem
        sys.modules.pop(name,None); importlib.invalidate_caches(); mod=importlib.import_module(name)
        missing=[n for n in EXPORTED_NAMES if not hasattr(mod,n)]
        if missing: raise RuntimeError("UMD-094 missing symbols: "+", ".join(missing))
        verifier=getattr(mod,[n for n in EXPORTED_NAMES if n.startswith("verify_")][0])
        if verifier() is not True: raise RuntimeError("UMD-094 verification returned false")
    finally:
        if str(ROOT) in sys.path: sys.path.remove(str(ROOT))

def sha256_file(path): return hashlib.sha256(path.read_bytes()).hexdigest()

def main():
    print("="*72); print(" UMD-094 INSTALLER"); print(" MARKET NORMALIZATION FOUNDATION"); print("="*72); print(f"[BOOT] Revision: {REVISION}"); print(f"[ROOT] {ROOT}")
    verify_upstream(); print("[PASS] Certified upstream verified read-only")
    backups={p:(p.read_bytes() if p.exists() else None) for p in (MODULE,INIT,TEST)}
    try:
        write_exact(MODULE,MODULE_SOURCE); write_exact(TEST,TEST_SOURCE); update_init()
        compile(MODULE.read_text(encoding="utf-8"),str(MODULE),"exec"); compile(INIT.read_text(encoding="utf-8"),str(INIT),"exec"); compile(TEST.read_text(encoding="utf-8"),str(TEST),"exec")
        verify_current()
    except Exception:
        for p,previous in backups.items():
            if previous is None:
                if p.exists(): p.unlink()
            else: p.write_bytes(previous)
        importlib.invalidate_caches(); print("[ROLLBACK] UMD-094 installation failed; all affected files restored"); raise
    manifest={"build_id":'UMD-094',"revision":REVISION,"production_module":MODULE.name,"test":TEST.name,"files":{str(MODULE.relative_to(ROOT)):sha256_file(MODULE),str(INIT.relative_to(ROOT)):sha256_file(INIT),str(TEST.relative_to(ROOT)):sha256_file(TEST)},"network_enabled":False,"persistence_enabled":False,"publication_enabled":False,"execution_enabled":False}
    h=hashlib.sha256(json.dumps(manifest,sort_keys=True,separators=(",",":")).encode()).hexdigest()
    print(f"[PASS] Wrote: {MODULE.relative_to(ROOT)}"); print(f"[PASS] Updated: {INIT.relative_to(ROOT)}"); print(f"[PASS] Wrote: {TEST.relative_to(ROOT)}"); print("[PASS] In-memory compilation verified"); print("[PASS] Required symbols and verifier certified"); print(f"[PASS] Deterministic install hash: {h}"); print("[PASS] Network, persistence, publication, and execution disabled"); print("[DONE] UMD-094 INSTALLATION COMPLETE"); return 0

if __name__=="__main__": raise SystemExit(main())
